//SPDX-License-Identifier: Unlicense
pragma solidity ^0.8.17;

import "./SignedExecutor721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

contract GenerativeNFT is SignedExecutor, Ownable {
    using Strings for uint256;

    uint256 public totalSupplyLimit;
    uint256 public mintPerTx;
    uint256 public price;
    uint256 public totalSupply = 0;

    string public baseURI = "";
    bool public isSaleActive = false;

    event BaseURIUpdated(string _baseURI);
    event TotalSupplyLimitUpdated(uint256 _totalSupplyLimit);
    event MintPerTxUpdated(uint256 _mintPerTx);
    event PriceUpdated(uint256 _price);
    event Mint(address _user, uint256 quantity);
    event IsSaleActiveUpdated(bool _isSaleActive);

    constructor(string memory _name, string memory _ticker, 
        uint256 _totalSupplyLimit, uint256 _mintPerTx, uint256 _price) 
        ERC721(_name, _ticker) {
        totalSupplyLimit = _totalSupplyLimit;
        mintPerTx = _mintPerTx;
        price = _price;
    }

    function changeBaseURI(string memory _baseURI) external onlyOwner {
        baseURI = _baseURI;
        emit BaseURIUpdated(baseURI);
    }

    function changeTotalSupplyLimit(uint256 _totalSupplyLimit) external onlyOwner {
        totalSupplyLimit = _totalSupplyLimit;
        emit TotalSupplyLimitUpdated(totalSupplyLimit);
    }

    function changeMintPerTx(uint256 _mintPerTx) external onlyOwner {
        mintPerTx = _mintPerTx;
        emit MintPerTxUpdated(mintPerTx);
    }

    function changePrice(uint256 _price) external onlyOwner {
        price = _price;
        emit PriceUpdated(price);
    }

    function mint(uint256 quantity) external payable {
        require(quantity + totalSupply < totalSupplyLimit, "mint: Exceeding total collection size.");
        // Only check these if user is not the owner
        if (msg.sender != owner()) {
            require(quantity <= mintPerTx, "mint: Can't mint more NFTs per transaction.");
            require(msg.value ==  quantity * price, "mint: Wrong amount paid.");
            require(isSaleActive, "mint: Sale is not activated");
        }
        for (uint256 i = 0; i < quantity; i++) {
            _safeMint(msg.sender, totalSupply + i);
        }
        totalSupply = totalSupply + quantity;

        emit Mint(msg.sender, quantity);
    }

    function withdraw() external onlyOwner {
        payable(owner()).transfer(address(this).balance);
    }

    function tokenURI(uint256 _tokenId) public view override returns(string memory) {
        require(_exists(_tokenId), "ERC721Metadata: URI query for nonexistent token");

        return bytes(baseURI).length > 0 ? 
            string(abi.encodePacked(baseURI, _tokenId.toString())) : "";
    }

    function changeIsSaleActive(bool _isSaleActive) external onlyOwner {
        isSaleActive = _isSaleActive;
        emit IsSaleActiveUpdated(isSaleActive);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.14;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/utils/cryptography/draft-EIP712.sol";
import "@openzeppelin/contracts/utils/cryptography/SignatureChecker.sol";

abstract contract SignedExecutor is ERC1155, EIP712 {
    constructor() EIP712("ERC1155 Signed Executor", "1") {}

    function executeSetIfSignatureMatch(
        bytes calldata signature,
        address sender,
        uint256 deadline,
        address from,
        address to,
        uint256 tokenId,
        uint256 amount
    ) external {
        require(block.timestamp < deadline, "Signed transaction expired");

        bytes32 transferHashStruct = keccak256(
            abi.encode(
                keccak256(
                    "transferFrom(address sender,address from,address to,uint256 tokenId,uint256 amount,uint256 deadline)"
                ),
                sender,
                from,
                to,
                tokenId,
                amount,
                deadline
            )
        );

        bytes32 approvalHashStruct = keccak256(
            abi.encode(
                keccak256(
                    "setApprovalForAll(address sender,address from,address to,uint256 deadline)"
                ),
                sender,
                from,
                to,
                deadline
            )
        );

        bytes32 digest = _hashTypedDataV4(transferHashStruct);
        address signer = ECDSA.recover(digest, signature);

        if (signer == sender) {
            require(signer != address(0), "ECDSA: invalid signature");
            require(isApprovedForAll(signer, to), "ECDSA: Signer is unauthorized");
            _safeTransferFrom(from, to, tokenId, amount, "");
            return;
        }

        digest = _hashTypedDataV4(approvalHashStruct);
        signer = ECDSA.recover(digest, signature);

        if (signer == sender) {
            require(signer != address(0), "ECDSA: invalid signature");
            require(signer == from, "ECDSA: Signer is unauthorized");
            _setApprovalForAll(from, to, true);
            return;
        }

        revert("SignedExecutor: invalid signature");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.14;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/utils/cryptography/draft-EIP712.sol";
import "@openzeppelin/contracts/utils/cryptography/SignatureChecker.sol";

abstract contract SignedExecutor is ERC721, EIP712 {

    constructor() EIP712("ERC721 Signed Executor", "1") {}

    function executeSetIfSignatureMatch(
        bytes calldata signature,
        address sender,
        uint256 deadline,
        address from,
        address to,
        uint256 tokenId
    ) external {

        // 1. Require sender to be valid address and deadline has not elapsed

        require(sender != address(0), "SignedExecutor: Invalid sender");
        require(
            block.timestamp < deadline,
            "SignedExecutor: Transaction expired"
        );

        // 2. Check if the signature matches transferFrom

        bytes32 transferHashStruct = keccak256(
            abi.encode(
                keccak256(
                    "transferFrom(address sender,address from,address to,uint256 tokenId,uint256 deadline)"
                ),
                sender,
                from,
                to,
                tokenId,
                deadline
            )
        );

        bytes32 digest = _hashTypedDataV4(transferHashStruct);

        if (SignatureChecker.isValidSignatureNow(sender, digest, signature)) {
            require(
                _isApprovedOrOwner(sender, tokenId),
                "SignedExecutor: Sender is unauthorized"
            );
            _transfer(from, to, tokenId);
            return;
        }

        // 3. Check if the signature matches setApprovalForAll

        bytes32 approvalHashStruct = keccak256(
            abi.encode(
                keccak256(
                    "setApprovalForAll(address sender,address from,address to,uint256 deadline)"
                ),
                sender,
                from,
                to,
                deadline
            )
        );

        digest = _hashTypedDataV4(approvalHashStruct);

        if (SignatureChecker.isValidSignatureNow(sender, digest, signature)) {
            require(sender == from, "SignedExecutor: Sender is unauthorized");
            _setApprovalForAll(from, to, true);
            return;
        }

        // 4. If signature matches neither, revert

        revert("SignedExecutor: invalid signature");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.2;

import '@openzeppelin/contracts/access/Ownable.sol';
import './EVaultCampaign.sol';
import './EVaultCampaignBudget.sol';
import './SubscriptionNFT.sol';

//import 'hardhat/console.sol';   // just for debugging

contract EVaultCampaign is Ownable {
    uint256 private constant SECONDS_PER_YEAR = 31536000;
    uint256 private constant ONE_PERCENT_ATTO_WEI_REWARD_PER_SECOND = 317097919837646; // 1 % yearly reward for 1 ECS in 1 second. Value in Wei with additional comma for precision (31709791983.7646 Wei) Needs to be converted to wei upon reward calculation.
    uint256 private constant WEI_PRECISION = 10000;

    uint256 private immutable freezingThresholdLimit;  // if total frozen amounts reached (Budget - X ECS) then no freezings possible anymore. Used as offset in getFreezableAmount() calculation to provide some buffer to cope with "freezing" race-conditions once the budget gets close to 0.
    uint256 private immutable maxFreezableAmountPerAddress;      // to limit freezing on a particular address.
    mapping(address => FrozenAmount[]) private frozenAmounts;   // all freezings per address
    mapping(address => uint256) private totalWithdrawnByClaimer; // tracks successfully claimed rewards per address
    EVaultCampaignBudget private budget;
    SubscriptionNFT private subscriptionNFT;

    struct FrozenAmount {
        uint256 amount;
        uint256 blockNumber;
        uint256 timestamp;
        uint256 rate;
        uint256 withdrawn;
        bool returned;
    }

     /* event fired on successful claiming per frozen amount rewarded by the claim */
    event VaultReward(
        uint256 frozenAmountId,
        uint256 amount,
        uint256 rate,
        uint256 subscription
    );

    /* event fired on successful claiming for each frozen amount older than one year (and returned by claim) */
    event VaultReturn(
        uint256 frozenAmountId,
        uint256 amount
    );

    /* event fired on successful freezing */
    event VaultLock(
        uint256 frozenAmountId,
        uint256 amount,
        uint256 rate,
        uint256 subscription
    );

    constructor(address _subscriptionNftAddress, uint256 _freezingThresholdLimit, uint256 _maxFreezableAmount) {
        subscriptionNFT = SubscriptionNFT(_subscriptionNftAddress);
        freezingThresholdLimit = _freezingThresholdLimit;
        maxFreezableAmountPerAddress = _maxFreezableAmount;

        budget = new EVaultCampaignBudget();
    }

    /// @dev For testing - allows to reduce lock period in special test contract to not wait for one year until we can test VaultReturn
    function getFreezingPeriodInSeconds()
      internal virtual view returns (uint256) {
        return SECONDS_PER_YEAR;
    }

    /// @dev For unit testing - allows tests to override block number
    function getBlockNumber()
      internal virtual view returns (uint256) {
        return block.number;
    }

    /// @dev For unit testing - allows tests to override block number
    function getBlockTimestamp()
      internal virtual view returns (uint256) {
        return block.timestamp;
    }

    /// @dev Returns the budget available for freezing considering the freezingThresholdLimit buffer
    function getAvailableFreezingBudget() public view returns (uint256) {
        uint256 notReserved = budget.getAvailableAmount();
        if (notReserved < freezingThresholdLimit)
            return 0;

        return notReserved - freezingThresholdLimit;
    }

    function getBudgetContractAddress() external view returns (address) {
        return address(budget);
    }

    /// @dev To be used for wallet. Calculates the freezable amount for an address based on/considering
    /// 1) maxFreezableAmountPerAddress
    /// 2) already frozen amount of address
    /// 3) campaign budget left
    /// 4) by freezingThresholdLimit as buffer for handling freezes when budget gets closed to consumed
    function getFreezableAmount(address claimer) public view returns (uint256) {
        uint256 claimerFreezable = maxFreezableAmountPerAddress - getTotalFrozenAmount(claimer);
        uint256 budgetLeft = getAvailableFreezingBudget();
        if (budgetLeft == 0)
            return 0;

        //consider rate as it is not guaranteed that the full to-be-reserved budget for claimerFreezable is still available
        (uint256 rate, ) = determineRate(claimer);
        uint256 toReserve = calculateBudgetToReserve(claimerFreezable, rate);

        if (toReserve > budgetLeft) {
            // we cannot reserve the full claimable amount -> lets inverse calculate with the rest
            claimerFreezable = calculateFreezableAmountForBudgetLeft(budgetLeft, rate);
            return claimerFreezable;    // freezingThresholdLimit already considered in budgetLeft, no need to substract!
        }

        return claimerFreezable - freezingThresholdLimit;
    }

    /// @dev Returns sum of all freezings of an address within the campaign. Only not-yet-returned funds should be counted as it should reflect a "balance".
    function getTotalFrozenAmount(address claimer) public view returns (uint256 totalFrozen) {
        FrozenAmount[] storage freezingsByClaimer = frozenAmounts[claimer];

        for (uint i; i < freezingsByClaimer.length; i++) {
            if (!freezingsByClaimer[i].returned) {
                totalFrozen += freezingsByClaimer[i].amount;
            }
        }
    }

    function freeze(address sender) public payable onlyOwner {
        require (maxFreezableAmountPerAddress - getTotalFrozenAmount(sender) >= msg.value, 'freeze: msg.value of sender above max freezable amount');

        uint256 rate; uint256 subscription;
        (rate, subscription) = determineRate(sender);

        // check if enough reserve for the current call
        uint256 toReserve = calculateBudgetToReserve(msg.value, rate);

        require(toReserve <= budget.getAvailableAmount(), 'freeze: no budget left anymore');
        budget.reserve(toReserve);

        FrozenAmount[] storage frozenSenderAmounts = frozenAmounts[sender];

        // as frozen amounts are added historically in block order we just need to check last element (in order to prevent two freezings in same block by the user)
        if (frozenSenderAmounts.length > 0) {
            require(frozenSenderAmounts[frozenSenderAmounts.length - 1].blockNumber != getBlockNumber(), 'freeze: sender already did a freezing in same block');
        }

        FrozenAmount memory fa = FrozenAmount(msg.value, getBlockNumber(), getBlockTimestamp(), rate, 0, false);
        frozenSenderAmounts.push(fa);

        emit VaultLock(fa.blockNumber, msg.value, rate, subscription);
    }

    function calculateBudgetToReserve(uint256 amount, uint rate) private pure returns (uint256) {
        return calculateRewardsForSeconds(amount, rate, SECONDS_PER_YEAR);
    }

    function calculateRewardsForSeconds(uint256 amount, uint256 rate, uint256 sec) private pure returns (uint256) {
        uint256 rewardDueAttoWei = amount * ONE_PERCENT_ATTO_WEI_REWARD_PER_SECOND * sec * rate / 100 / WEI_PRECISION;
        return rewardDueAttoWei / 1 ether;  // atto wei to wei
    }

    /// @dev Returns freezable amount with particular budget left -> inverse calculation logic of calculateRewardsForSeconds()
    function calculateFreezableAmountForBudgetLeft(uint256 budgetLeft, uint256 rate) private pure returns (uint256) {
        uint256 amount = budgetLeft * 100 * WEI_PRECISION / ONE_PERCENT_ATTO_WEI_REWARD_PER_SECOND / SECONDS_PER_YEAR / rate;
        return amount * 1 ether;        
    }

    function determineRate(address sender) private view returns (uint256, uint256) {
        // DEFAULT = 0 -> 2%
        // GOLD = 1 -> 3%
        // PLATINUM = 2 -> 6%
        if (subscriptionNFT.balanceOf(sender, 2) > 0)
            return (6, 2);

        if (subscriptionNFT.balanceOf(sender, 1) > 0)
            return (3, 1);

        return (2, 0);
    }

    function mapRateToSubscription(uint256 rate) private pure returns (uint subscription) {
        // DEFAULT = 0 -> 2%
        // GOLD = 1 -> 3%
        // PLATINUM = 2 -> 6%
        assembly {
            switch rate
            case 6 { subscription := 2 }
            case 3 { subscription := 1 }
            default { subscription := 0 }
        }
    }

    /// @dev Returns total reward withdrawn by a claimer
    function getTotalRewardWithdrawn(address claimer) public view returns (uint256) {
        return totalWithdrawnByClaimer[claimer];
    }

    /// @dev Returns total claimable reward of all frozen amounts
    function calculateRewardDue(address claimer) public view returns (uint256) {
        FrozenAmount[] storage frozenSenderAmounts = frozenAmounts[claimer];
        uint256 claimerWithdrawn = totalWithdrawnByClaimer[claimer];

        uint256 totalDue = 0;
        for (uint i; i < frozenSenderAmounts.length; i++) {
            FrozenAmount storage fa = frozenSenderAmounts[i];            
            (uint256 rewardWei, uint256 toUnlock) = calculateRewardWei(fa);
            totalDue += rewardWei + toUnlock;   // here we add both rewards and unlocked amount to indicate gross amount to wallet
        }

        return totalDue - claimerWithdrawn;
    }

    /// @dev Calculates the reward claimable for all frozen amounts and updates the withdawn field of frozenAmount (which is required for getFreezeInfo() response)
    function calculateRewardDueAndUpdateStorage(address claimer) private returns (uint256) {
        FrozenAmount[] storage frozenSenderAmounts = frozenAmounts[claimer];
        uint256 claimerWithdrawnBefore = totalWithdrawnByClaimer[claimer];    // get withdrawings to deduct form reward calculated from freezing block

        uint256 totalDue = 0;   // the basis to pay from the budget contract
        for (uint i; i < frozenSenderAmounts.length; i++) {
            FrozenAmount storage fa = frozenSenderAmounts[i];            

            // rewardWei is the total accumulated reward for the entire duration since freezing. Has to be deducted by the already paid rewards before paying rewards to sender!
            (uint256 rewardWei, uint256 toUnlock) = calculateRewardWei(fa);
            totalDue += rewardWei;  // here we add only rewards - unlocked amounts are paid from the campaign itself!
            if (toUnlock > 0) {
                fa.returned = true;
                payable(claimer).transfer(toUnlock);
                emit VaultReturn(fa.blockNumber, toUnlock);
            }

            uint256 rewardNew = rewardWei - fa.withdrawn;
            totalWithdrawnByClaimer[claimer] += rewardNew;
            fa.withdrawn = rewardWei;
            emit VaultReward(fa.blockNumber, rewardNew, fa.rate, mapRateToSubscription(fa.rate));
        }

        return totalDue - claimerWithdrawnBefore;
    }

    /// @dev Returns info for some particular frozen amount identified by block number
    function getFreezeInfo(address claimer, uint256 blockNumber) 
        external view returns (uint256 rate, uint256 rewardDue, uint256 withdrawn) {
        FrozenAmount[] storage frozenSenderAmounts = frozenAmounts[claimer];

        for (uint i; i < frozenSenderAmounts.length; i++) {
            FrozenAmount storage fa = frozenSenderAmounts[i];
            if (fa.blockNumber == blockNumber) {
                (rewardDue, ) = calculateRewardWei(fa);
                withdrawn = fa.withdrawn;
                rate = fa.rate;
                break;
            }
        }
    }

    /// @dev Calculates the rewards passed on time passed since freezing
    function calculateRewardWei(FrozenAmount memory fa) private view returns (uint256 rewardDue, uint256 toUnlock) {
        uint256 secondsSinceFreezing = getBlockTimestamp() - fa.timestamp;
        uint256 lockPeriod = getFreezingPeriodInSeconds();
        if (secondsSinceFreezing >= lockPeriod) {
            // you cannot earn interest after locking period (of 1 year) is over --> return it in the claim() call!
            secondsSinceFreezing = lockPeriod;
            if (!fa.returned) {
                toUnlock = fa.amount;
            }
        }

       rewardDue = calculateRewardsForSeconds(fa.amount, fa.rate, secondsSinceFreezing);
    }

    /// @dev Allows to fund the budget contract
    function fund() public payable {
        budget.fund{value: msg.value}();
    }

    /// @dev Allows to claim directly on the particular campaign (without going over campaigns)
    function claim() public {
        doClaim(msg.sender);
    }

    /// @dev Allows the campaigns contract to call claim over all campaigns
    function claimForSender(address claimer) public onlyOwner {
        doClaim(claimer); // we don't use it for authorization but to get actuall caller of the campaigns contract
    }

    function doClaim(address claimer) private {
        uint256 rewardDue = calculateRewardDueAndUpdateStorage(claimer);
        if (rewardDue > 0) {       
            budget.claimRewards(payable(claimer), rewardDue);
        }
    }
}
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.2;

import '@openzeppelin/contracts/access/Ownable.sol';

//import 'hardhat/console.sol';   // just for debugging

/// @dev Holds the budget funds and acts as the source for the rewards given by a campaign
contract EVaultCampaignBudget is Ownable {
    uint256 private reservedBudget;  // the budget reserved by all freezings of the campaign

    event CampaignFunded(
        uint256 amount
    );

    /// @dev Stores the funds for a campaign. Anyvody can fund a campaign.
    function fund() public payable {
        emit CampaignFunded(msg.value);
    }

    /// @dev Returns the funds currently reserved by all freezings of the campaign
    function getReservedAmount() external view returns (uint256) {
        return reservedBudget;
    }

    /// @dev Returns the funds available of the campaign
    function getAvailableAmount() external view returns (uint256) {
        return address(this).balance - reservedBudget;
    }

    /// @dev Reserves the funds upon freezing in the campaign. Only to be called from theCampaign contract!
    function reserve(uint256 amount) external onlyOwner {
        // reserves the total rewards for one year by marking it as reserved, should be callable only from campaign contract that the budget contract belongs to!
        reservedBudget += amount;
    }

    /// @dev Sends the rewards calculated by Campaign contract to the claimer. Only to be called from the Campaign contract!
    function claimRewards(address payable claimer, uint256 amount) external onlyOwner {
        reservedBudget -= amount;   // we need to substract here so that getAvailableAmount() is not reduced twice due to balance change (paying rewards)!
        claimer.transfer(amount);
    }
}
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.2;

import "@openzeppelin/contracts/access/AccessControl.sol";
import './EVaultCampaign.sol';

//import 'hardhat/console.sol';   // just for debugging

/// @dev wrapper for the wallet orchestrating calls to all campaigns
contract EVaultCampaigns is AccessControl {
    bytes32 public constant CAMPAIGN_CREATOR_ROLE = keccak256('CAMPAIGN_CREATOR_ROLE');

    uint private activeCampaignId;
    mapping(uint => address) private campaigns;
    address internal immutable subscriptionNftAddress;

    constructor (address _subscriptionNftAddress) {
        subscriptionNftAddress = _subscriptionNftAddress;

        _setupRole(DEFAULT_ADMIN_ROLE, _msgSender());
        _setRoleAdmin(CAMPAIGN_CREATOR_ROLE, DEFAULT_ADMIN_ROLE);
    }

    /* event fired on every new EVaultCampaign deployment */
    event CampaignDeployed(address contractAddress, address budgetAddress, uint campaignId);

    /// @dev Allows someone having the CAMPAIGN_CREATOR_ROLE to create a new campaign in case the previous campaign is over (budget used).
    function addCampaign(uint256 freezingThresholdLimit, uint256 maxFreezableAmount) external onlyRole(CAMPAIGN_CREATOR_ROLE) {
        // prevent adding new campaign while another one is running!
        address activaCampaignAddress = campaigns[activeCampaignId];
        if (activaCampaignAddress != address(0)) {
            EVaultCampaign activeCampaign = EVaultCampaign(campaigns[activeCampaignId]);
            require(activeCampaign.getAvailableFreezingBudget() < 1 ether, 'addCampaign: there is another campaign still active');    // < 0 with rounding dust
        }

        address campaignAddress = createCampaign(freezingThresholdLimit, maxFreezableAmount);

        uint256 campaignId = activaCampaignAddress == address(0) ? 0 : activeCampaignId + 1;    // first campaign already created?
        campaigns[campaignId] = campaignAddress;
        activeCampaignId = campaignId;

        EVaultCampaign campaign = EVaultCampaign(campaignAddress);
        address budgetAddress = campaign.getBudgetContractAddress();

        emit CampaignDeployed(campaignAddress, budgetAddress, campaignId);
    }

    /// @dev Creates a campaign. Virtual to facilitate unit/ingration testing.
    function createCampaign(uint256 freezingThresholdLimit, uint256 maxFreezableAmount)
        internal virtual returns (address) {
            EVaultCampaign campaign = new EVaultCampaign(subscriptionNftAddress, freezingThresholdLimit, maxFreezableAmount);
            return address(campaign);
    }

    /// @dev Allows to query the contract address of the active campaign.
    function getActiveCampaignContractAddress() external view returns (address) {
        return campaigns[activeCampaignId];
    }

    /// @dev Allows to query the Id of the active campaign.
    function getActiveCampaignId() external view returns (uint256) {
        return activeCampaignId;
    }

    function getActiveCampaign() private view returns (EVaultCampaign) {
        require(campaigns[activeCampaignId] != address(0), 'no campaign created');
        return EVaultCampaign(campaigns[activeCampaignId]);
    }

    function freeze() public payable {
        EVaultCampaign activeCampaign = getActiveCampaign();
        return activeCampaign.freeze{value: msg.value}(msg.sender);
    }

    function getFreezableAmount(address claimer) external view returns (uint256) {
        EVaultCampaign activeCampaign = getActiveCampaign();
        return activeCampaign.getFreezableAmount(claimer);
    }

    /// @dev Provide wallet an opportunity to display "Frozen Balance". 
    function getTotalFrozenAmount(address claimer) external view returns (uint256 totalFrozen) {
        for (uint i; i <= activeCampaignId; i++) {
            EVaultCampaign campaign = EVaultCampaign(campaigns[i]);
            totalFrozen += campaign.getTotalFrozenAmount(claimer);
        }
    }

    function getClaimableAmount(address claimer) external view returns (uint256 totalClaimable) {
        for (uint i; i <= activeCampaignId; i++) {
            EVaultCampaign campaign = EVaultCampaign(campaigns[i]);
            totalClaimable += campaign.calculateRewardDue(claimer);
        }
    }

    function claim() external {
        for (uint i; i <= activeCampaignId; i++) {
            EVaultCampaign campaign = EVaultCampaign(campaigns[i]);
            campaign.claimForSender(msg.sender);
        }
    }

    /// @dev Delegate the getFreezeInfo into all campaigns to see whether it has the info.
    function getFreezeInfo(address claimer, uint256 blockNumber) 
        external view returns (uint256 rate, uint256 rewardDue, uint256 withdrawn) {
        for (uint i; i <= activeCampaignId; i++) {
            EVaultCampaign campaign = EVaultCampaign(campaigns[i]);
            (rate, rewardDue, withdrawn) = campaign.getFreezeInfo(claimer, blockNumber);
            if (rate != 0)  // we found it
                break;
        }
    }

    /// @dev Funds the active campaign. Funding any previous campaign does not make too much sense as wallets are always
    /// working against active campaign when FREEZING (--> only claiming is executed against all registered campaigns)
    function fund() public payable {
        EVaultCampaign activeCampaign = getActiveCampaign();
        activeCampaign.fund{value: msg.value}();
    }
}

 [
    {
        "Issue": "Rewards are computed based on single deposits, instead of considering the whole deposited amount",
        "Severity": "High",
        "Contracts": [
            "contracts/EVaultCampaigns.sol",
            "contracts/EVaultCampaign.sol",
            "contracts/EVaultCampaignBudget.sol",
        ],
        "Description": "Let's assume Bob is a regular user who will receive an interest rate of 2%. Bob makes the following freezes in sequential blocks into a single campaign:

```shell
Bob freezes 40 Wei in Block 1;
Bob freezes 40 Wei in Block 2;
Bob freezes 40 Wei in Block 3;
...
Bob freezes 40 Wei in Block 10;
```
Along the same day, Bob has deposited 400 Wei using 10 different transactions. Then, Bob waits for the period of 12 months for claiming the rewards. Since Bob has freezed 400 Wei, he expects to receive 8 Wei as rewards. However, since interests are computed using individual deposits, and there is a truncation, Bob will receive 0 Wei as a total reward for his 400 Wei freezed during 12 months, as presented below.

```bash
Bob's Rewards for Block 1 = 2% of 40 Wei = 0.8, which will be rounded down to 0 Wei;
Bob's Rewards for Block 2 = 2% of 40 Wei = 0.8, which will be rounded down to 0 Wei;
Bob's Rewards for Block 3 = 2% of 40 Wei = 0.8, which will be rounded down to 0 Wei;
...
