contract OnlyOwnerCollection is Initializable, UUPSUpgradeable, ERC721URIStorageUpgradeable, OwnableUpgradeable {

    /// @notice Emitted when a new token is minted.
    /// @param contractAddress The address of the contract where the token is minted.
