    /**
     * @dev Mints a new NFT. Can only be called by the owner
     * @param recipient Address to receive the minted token.
     * @param tokenURI URI for the minted token.
     * @return uint256 Returns the ID of the minted token.
     */
    function mintNFT(address recipient, string memory tokenURI) public returns (uint256) {
        require(msg.sender == owner(), "Not owner or approved.");

        _tokenIds.increment();
        uint256 newItemId = _tokenIds.current();

        _mint(recipient, newItemId);
        _setTokenURI(newItemId, tokenURI);

        emit OnlyOwnerCollectionMint(recipient, tokenURI);

        return newItemId;
    }
}
