import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";


/**
 * @title Bid
 * @dev Represents a bid in a Vickrey auction.
 */
contract Bid is ReentrancyGuard {
    uint256 public bidAmount;
    address public bidder;
    IAuctioneer public auctioneer;
    uint256 public auctionId;
    IERC20 public currency;
    bool winner;
    bool withdrawn;

    /**
     * @dev Constructs a new Bid.
     * @param _auctioneer Address of the auctioneer.
     * @param _auctionId Identifier of the auction.
     * @param _bidder Address of the bidder.
     * @param _bidAmount Amount of the bid.
     * @param _currency Address of the currency (0 address if ETH).
     */
    constructor(address _auctioneer, uint256 _auctionId, address _bidder, uint256 _bidAmount, address _currency) payable {
      currency = IERC20(_currency);

      if (address(currency) == address(0)) {
          require(address(this).balance >= _bidAmount, "Insufficient funds in contract");
      } else {
          require(currency.balanceOf(address(this)) >= bidAmount, "Insufficient token balance in contract");
      }

      bidder = _bidder;
      bidAmount = _bidAmount;
      auctioneer = IAuctioneer(_auctioneer);
      auctionId = _auctionId;
    }

    function getBidder() public view returns (address) {
      return bidder;
    }

    function getCurrency() public view returns (address) {
      return address(currency);
    }

    function getBidAmount() public view returns (uint256) {
      return bidAmount;
    }


    function getAuctionId() public view returns (uint256) {
      return auctionId;
    }

    function getAuctioneer() public view returns (address) {
      return address(auctioneer);
    }

    /**
     * @notice Declare the winner of the bid and transfer the winning amount.
     * @param seller The address to receive the winning amount.
     * @param winAmount The winning amount (2nd highest bid in a Vickrey auction).
     */
    function win(address seller, uint256 winAmount) external nonReentrant {
      require(msg.sender == address(auctioneer), "Only the auctioneer can declare a winner");
      require(!winner, "Already declared winner");
      require(withdrawn == false, "Already withdrawn");
      winner = true;
      withdrawn = true;
      if (address(currency) == address(0)) {
          // If the bid is in native currency, transfer the bid amount to the seller
          (bool success, ) = payable(seller).call{value: winAmount}("");
          require(success, "Transfer failed");
      } else {
          // If the bid is in ERC20 tokens, transfer the tokens to the seller
          require(currency.transfer(seller, winAmount), "Transfer failed");
      }
    }

    /**
     * @notice Allows the bidder to withdraw their bid amount if not declared the winner.
     */
    function withdraw() external nonReentrant {
        require(auctioneer.getAuctionSettled(auctionId), "Auction not settled.");
        require(winner == false, "Not winner");
        require(withdrawn == false, "Already withdrawn");
        withdrawn = true;

        if (address(currency) == address(0)) {
            // If the bid is in native currency, allow the bidder to withdraw their bid amount
            (bool success, ) = payable(bidder).call{value: bidAmount}("");
            require(success, "Transfer failed");
        } else {
            // If the bid is in ERC20 tokens, allow the bidder to withdraw their bid amount
            require(currency.transfer(bidder, bidAmount), "Transfer failed");
        }
    }

    receive() external payable {}
}

pragma solidity ^0.8.19;

import "@matterlabs/zksync-contracts/l2/system-contracts/Constants.sol";
import "@matterlabs/zksync-contracts/l2/system-contracts/libraries/SystemContractsCaller.sol";

contract BidFactory {
    bytes32 public bytecodeHash;
    address auctioneer;

    /**
     * @dev Constructs a new BidFactory.
     * @param _bytecodeHash Hash of the bytecode for bid contracts.
     */
    constructor(bytes32 _bytecodeHash) {
        bytecodeHash = _bytecodeHash;
    }

    modifier onlyAuctioneer() {
        require(auctioneer != address(0) && msg.sender == auctioneer, "Only the auctioneer can deploy bids");
        _;
    }

    /**
     * @notice Set the auctioneer address.
     * @dev Can only be called once.
     * @param _auctioneer The address of the auctioneer.
     */
    function setAuctioneer(address _auctioneer) external {
        require(auctioneer == address(0), "Auctioneer already set");
        auctioneer = _auctioneer;
    }

    /**
     * @notice Deploys a new bid contract.
     * @param salt A unique salt for generating the bid contract address.
     * @param _auctionId Identifier for the auction.
     * @param _bidder Address of the bidder.
     * @param _bidAmount Amount of the bid.
     * @param _currency Address of the currency (0 address if ETH).
     * @return bidAddress Address of the newly deployed bid contract.
     */
    function deployBid(
        bytes32 salt,
        uint256 _auctionId, 
        address _bidder, 
        uint256 _bidAmount, 
        address _currency
    ) onlyAuctioneer external returns (address bidAddress) {
        (bool success, bytes memory returnData) = SystemContractsCaller
            .systemCallWithReturndata(
                uint32(gasleft()),
                address(DEPLOYER_SYSTEM_CONTRACT),
                uint128(0),
                abi.encodeCall(
                    DEPLOYER_SYSTEM_CONTRACT.create2,
                    (salt, bytecodeHash, abi.encode(auctioneer, _auctionId, _bidder, _bidAmount, _currency))
                )
            );
        require(success, "Deployment failed");

        (bidAddress) = abi.decode(returnData, (address));
    }
}

