import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC1155} from "@openzeppelin/contracts/token/ERC1155/IERC1155.sol";
import {IERC1155Receiver} from "@openzeppelin/contracts/token/ERC1155/IERC1155Receiver.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {BidFactory} from "./BidFactory.sol";
import {Bid} from "./Bid.sol";


/**
 * @title Sealed Bids Auction a.k.a. DRA (Deferred Revelation Auction) Contract
 * @dev This contract is responsible for handling auctions, revealing bids, and transferring tokens.
 */
contract BulkSemaphore is Ownable, ReentrancyGuard, IERC721Receiver, IERC1155Receiver {
  event GroupCreated(address user, uint256 groupId);
  event ActionTaken(uint256 groupId, address user);
  event Reveal(bytes32 salt, address auctioneer, uint256 bidTimestamp, uint256 bidCommitment);

  IVerifier verifier;
  mapping(uint256 => bool) public revealed;
  mapping(address => bool) public bids;
  mapping(bytes32 => bool) public usedProofs;
  mapping(uint256 => uint256) public groupIdToRevealedCount;
  mapping(bytes32 => bool) public associatedProofs;
  uint256 public currentAuctionId = 0;
  mapping(uint256 => bool) public groups;
  uint256 public REVEAL_PERIOD = 60 * 60 * 2;

  /**
   * @notice Creates a new DRA contract instance.
   * @param _verifier Address of the ZK proof verifier contract.
   */
  constructor(address _verifier) {
    verifier = IVerifier(_verifier);
  }

  /**
   * @notice Starts a group.
   * @param _groupId Group ID
   */
  function createGroup(uint256 _groupId) public {
    require(groups[_groupId] == false, "Already created");
    groups[_groupId] = true;
    emit GroupCreated(msg.sender, _groupId);
  }

  /**
   * @notice Reveals a commitment on-chain.
   */
  function reveal(bytes32 salt, uint256 _groupId, uint256 _timestamp, uint256 _commitment)  external nonReentrant {
    require(revealed[_commitment] != true, "Bid already revealed.");
    groupIdToRevealedCount[_groupId] += 1;
    revealed[_commitment] = true;
    emit Reveal(salt, address(this), _timestamp, _commitment);    
  }

  /**
    * @notice Checks if a given proof has already been associated.
    * @param proofHash The hash of the proof and associated data.
    * @return boolean indicating if the proof has been associated.
  */
  function isProofAssociated(bytes32 proofHash) external view returns (bool) {
      return associatedProofs[proofHash];
  }

  /**
    * @notice Associates a given proof with an auction id and result.
    * @dev This association prevents proof submissions with mismatching auctions and results.
    * @param proofHash The hash of the proof and associated data.
  */
  function associateProof(bytes32 proofHash) external nonReentrant {
      require(!associatedProofs[proofHash], "Proof has already been associated");
      associatedProofs[proofHash] = true;
  }

  /**
   * @notice Ends an auction, transferring funds and tokens accordingly.
   * @param groupId ID of the group.
    * @param merkleRoot merkle root of the zk tree
   * @param _pA Part A of the ZK proof.
   * @param _pB Part B of the ZK proof.
   * @param _pC Part C of the ZK proof.
   * @param _pubSignals Public signals for the ZK proof.
   */
  function verifyProofs(uint256 groupId, uint256 merkleRoot, uint[2] calldata _pA, uint[2][2] calldata _pB, uint[2] calldata _pC, uint[68] calldata _pubSignals) external nonReentrant {
    bytes32 associatedHash = keccak256(abi.encodePacked(_pA, _pB, _pC, _pubSignals, auctionId, winningBid, winningAmount, merkleRoot));
    require(associatedProofs[associatedHash], "Proof was not previously associated");

    bytes32 proofHash = keccak256(abi.encodePacked(_pA, _pB, _pC, _pubSignals));
    require(!usedProofs[proofHash], "Proof has already been used");
    usedProofs[proofHash] = true;
    require(verifier.verifyProof(_pA, _pB, _pC, _pubSignals), "Invalid proof");

    // Take action
    emit ActionTaken(groupId, msg.sender);
  }

  /**
   * @notice Fetches the reveal status of a bid.
   * @param _bidCommitment Commitment hash of the bid.
   * @return A boolean indicating if the bid has been revealed.
  */
  function getRevealed(uint256 _bidCommitment) external view returns (bool) {
    return revealed[_bidCommitment];
  }

  function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data) external override returns (bytes4) {
    return this.onERC721Received.selector;
  }

  function onERC1155Received(address operator, address from, uint256 id, uint256 value, bytes calldata data) external override returns (bytes4) {
    return this.onERC1155Received.selector;
  }

  function onERC1155BatchReceived(address operator, address from, uint256[] calldata ids, uint256[] calldata values, bytes calldata data) external override returns (bytes4) {
    return this.onERC1155BatchReceived.selector;
  }

  function supportsInterface(bytes4 interfaceId) public view virtual override returns (bool) {
    return interfaceId == type(IERC721Receiver).interfaceId
        || interfaceId == type(IERC1155Receiver).interfaceId;
  }

  receive() external payable { }
}
