pragma solidity ^0.8.0;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC20, SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title BlockframeRevenue
 * @dev Store Blockframe's revenue
 */
contract BlockframeRevenue is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public multiSig; // Multi-signature address
    uint256 public constant PRECISION_FACTOR = 10**18;

    /**
     * @notice Emitted when an internal claim action is taken.
     * @param currency The address of the currency being claimed.
     * @param amount The amount of the currency being claimed.
     * @param caller The address initiating the claim.
     */
    event InternalClaim(address currency, uint256 amount, address caller);

    /**
     * @dev Sets the multi-sig address.
     * @param _multiSig The address of the multi-sig.
     */
    constructor(address _multiSig) {
        multiSig = _multiSig;
    }

    /**
     * @notice Allows the multi-sig to claim a specified currency amount.
     * @param currency The address of the currency. Use address(0) for native currency (ETH).
     * @param amount The amount of the currency to claim.
     */
    function internalClaim(address currency, uint256 amount) external nonReentrant {
        require(msg.sender == multiSig, "Sender is not authorized");
        require(amount >= PRECISION_FACTOR, "Deposit: Amount must be >= 1 FRAME");

